import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";import{Gt as i,Ht as a,Jt as o,Kt as s,Ut as c,Wt as l,qt as u}from"./chunks/assets.DAjhvrpn.js";var d=JSON.parse(`{"title":"Reward","description":"","frontmatter":{"title":"Reward","lang":"en-US"},"headers":[],"relativePath":"building/reward.md","filePath":"building/reward.md"}`),f={name:`building/reward.md`};function p(n,d,f,p,m,h){return e(),r(`div`,null,[...d[0]||=[t(`<h1 id="reward" tabindex="-1">Reward <a class="header-anchor" href="#reward" aria-label="Permalink to “Reward”">​</a></h1><p>The reward module consists of an open syringe holding the reward liquid, which is dispensed to the mice through a lick spout controlled by a solenoid valve.</p><figure><img src="`+o+`" alt="Reward spout module" width="1280" height="932" loading="lazy"><figcaption>Reward spout module</figcaption></figure><h2 id="solenoid-valve-assembly" tabindex="-1">Solenoid valve assembly <a class="header-anchor" href="#solenoid-valve-assembly" aria-label="Permalink to “Solenoid valve assembly”">​</a></h2><p>The solenoid valve assembly consists of a standard plastic 60 mL syringe at the top of the rig, connected to a solenoid valve with Tygon PVC (dairy) tubing. Since the module is gravity fed, we recommend placing the syringe as high as possible. The syringe can be mounted on the top frame of the rig cabinet with a 15/16&quot; cable holder (you can use some Thorlabs parts on top of the rig to raise the syringe higher). Remove the plunger from the syringe and use a Luer lock to 1/16&quot; ID tubing fitting to connect the syringe to the solenoid valve (we use the 003-0096-900 model from Parker).</p><figure><img src="`+u+`" alt="Reward syringe and solenoid valve; reward module assembly on the right." width="1280" height="932" loading="lazy"><figcaption>Reward syringe and solenoid valve; reward module assembly on the right.</figcaption></figure><p>To mount the reward solenoid valve on the DIN rail, we use a 3D printed part. The solenoid valve is attached to it with 4-40 x 3/16&quot; long screws, and a DIN rail clip with no. 8, 5/16&quot; long rounded head thread-forming screws. Assemble them as shown in the picture below and attach the assembly to the bottom DIN rail.</p><figure><img src="`+s+`" alt="" width="1280" height="932" loading="lazy"></figure><p>Finally, connect the syringe to the IN port of the solenoid valve and connect the OUT port to the spout inside the rig, using 1/16&quot; ID, 1/8&quot; OD Tygon soft tubing for food, beverage and dairy.</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>We don&#39;t route this tubing through the cable carrier because it has to be replaced every month, and that would make maintenance time consuming.</p></div><h2 id="lick-spout-holder-assembly" tabindex="-1">Lick spout holder assembly <a class="header-anchor" href="#lick-spout-holder-assembly" aria-label="Permalink to “Lick spout holder assembly”">​</a></h2><p>The lick spout holder is fixed in the sagittal and coronal planes and adjustable in Z (height), which reduces the variability in the relative position of the mouse and the spout. To this end, we designed a 3D printed arm that holds the spout holder (which also serves as the air puff delivery system). The arm is attached to a kinematic base, so it is easy to remove and replace when the Styrofoam ball needs to be taken out. The kinematic base is screwed to a dovetail translation stage with 1/4&quot; of travel to adjust the height of the spout.</p><p>To assemble it, follow these steps.</p><ol><li>Print the arm or have it printed (we recommend an external service and PA12GB material) and install an 8-32 thread, 0.312&quot; installed length heat-set insert for plastic in the hole in the lower part of the arm that attaches to the kinematic base. Then, screw the top part of the Thorlabs KB1X1 kinematic base to the arm with an 8-32 thread, 1/4&quot; long low-profile screw.</li></ol><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>To install the heat-set insert, follow step 3 of the bottom plate assembly in the <a href="/building/stage.html">stage</a> section.</p></div><figure><img src="`+i+`" alt="" width="1280" height="932" loading="lazy"></figure><ol start="2"><li>Install the 1/16&quot; tube ID x 10-32 male barbed fitting in the back of the spout holder and attach the holder to the arm with a pair of 2-56 thread, 5/32&quot; long screws. Put the FNS-18-2-2 straight feeding needle from Kent Scientific in the spout holder and fix the top part of the holder with four 100 degree countersink, 0-80 thread, 7/32&quot; long screws.</li></ol><figure><img src="`+l+`" alt="" width="1280" height="932" loading="lazy"></figure><ol start="3"><li>Print the breadboard-to-DT12 adapter or have it printed, and screw the Thorlabs DT12 dovetail translation stage to the adapter with an 8-32 thread, 3/8&quot; long flat head screw, making sure the stage&#39;s adjustment screw faces up (toward the ceiling of the rig). Attach the bottom part of the Thorlabs KB1X1 kinematic base to the other end with an 8-32 thread, 1/4&quot; long low-profile screw. Finally, install the assembly on the breadboard with a pair of 1/4&quot;-20 thread, 11/16&quot; long flat head screws.</li></ol><figure><img src="`+c+`" alt="" width="1280" height="932" loading="lazy"></figure><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Due to inaccuracies in the 3D printed part, the spout might be out of position. If so, we recommend using the alternative printed breadboard-to-DT12 adapter shown in the picture below, which lets you adjust the position of the reward spout.</p><figure><img src="`+a+`" alt="" width="1280" height="932" loading="lazy"></figure></div><ol start="4"><li>Finally, put the arm with the spout holder in place by joining the top and bottom parts of the kinematic base.</li></ol>`,22)]])}var m=n(f,[[`render`,p]]);export{d as __pageData,m as default};